{
  "name": "@afterrealism/opencode-voice",
  "version": "1.0.0",
  "description": "Local voice dictation for OpenCode on Linux using whisper.cpp and Ollama",
  "type": "module",
  "main": "dist/src/index.js",
  "types": "dist/src/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/src/index.d.ts",
      "import": "./dist/src/index.js"
    },
    "./tui": {
      "types": "./dist/src/index.d.ts",
      "import": "./dist/src/index.js"
    }
  },
  "bin": {
    "opencode-voice": "dist/src/doctor.js"
  },
  "files": ["dist/src", "README.md", "LICENSE"],
  "engines": { "node": ">=22" },
  "scripts": {
    "build": "tsc -p tsconfig.json",
    "test": "npm run build && node --test dist/test/*.test.js",
    "pack:check": "npm pack --dry-run"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/afterrealism/opencode-voice.git"
  },
  "bugs": { "url": "https://github.com/afterrealism/opencode-voice/issues" },
  "homepage": "https://github.com/afterrealism/opencode-voice#readme",
  "keywords": ["opencode-plugin", "voice", "dictation", "whisper", "speech-to-text", "linux", "privacy"],
  "author": "After Realism",
  "license": "MIT",
  "publishConfig": { "access": "public" },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.1",
    "@types/node": "24.12.2",
    "typescript": "5.8.2"
  }
}
